// Seeds the product catalogue from the real Nature's Hair POS export (SKU,
// description, POS price, stock on hand), plus one admin account when
// ADMIN_EMAIL/ADMIN_PASSWORD are set. Run with `npm run db:seed`.
//
// SKUs are the real POS barcodes, not synthetic HSA-* codes. brand/category
// were inferred from the description text (known-brand match, then keyword
// rules) since the POS export doesn't carry those columns separately —
// expect some to need a manual touch-up via /admin/products.
import { config } from "dotenv";
import { notInArray, sql } from "drizzle-orm";
import { hashPassword } from "../lib/password";

config({ path: ".env.local" });

import { db } from "./index";
import { products, users } from "./schema";

type SeedProduct = {
  sku: string;
  name: string;
  brand: string;
  category: string;
  retailCents: number;
  stockQty: number;
};

