async function seed() {
  // Full catalogue replacement: drop any product not in this sheet (old
  // placeholder seed data, discontinued lines). Safe only because no order
  // has ever referenced a product row yet in this environment — order_items.
  // productId has no cascade, so this would throw a FK error otherwise.
  const currentSkus = SEED_PRODUCTS.map((p) => p.sku);
  const removed = await db
    .delete(products)
    .where(notInArray(products.sku, currentSkus))
    .returning({ sku: products.sku });
  if (removed.length > 0) {
    console.log(`Removed ${removed.length} product(s) no longer in the sheet.`);
  }

  for (const p of SEED_PRODUCTS) {
    await db
      .insert(products)
      .values({
        sku: p.sku,
        name: p.name,
        brand: p.brand,
        category: p.category,
        retailPriceCents: p.retailCents,
        stockQty: p.stockQty,
        imageUrl: null,
        active: true,
      })
      .onConflictDoUpdate({
        target: products.sku,
        set: {
          name: sql`excluded.name`,
          brand: sql`excluded.brand`,
          category: sql`excluded.category`,
          retailPriceCents: sql`excluded.retail_price_cents`,
          stockQty: sql`excluded.stock_qty`,
          active: sql`excluded.active`,
        },
      });
  }
  console.log(`Seeded ${SEED_PRODUCTS.length} products.`);

  const adminEmail = process.env.ADMIN_EMAIL;
  const adminPassword = process.env.ADMIN_PASSWORD;
  if (adminEmail && adminPassword) {
    const passwordHash = await hashPassword(adminPassword);
    await db
      .insert(users)
      .values({
        role: "admin",
        name: "Admin",
        email: adminEmail,
        phone: "0000000000",
        passwordHash,
      })
      .onConflictDoUpdate({
        target: users.email,
        set: { passwordHash: sql`excluded.password_hash`, role: sql`excluded.role` },
      });
    console.log(`Seeded admin account ${adminEmail}.`);
  } else {
    console.log("ADMIN_EMAIL/ADMIN_PASSWORD not set — skipped admin seed.");
  }

  process.exit(0);
}

seed().catch((err) => {
  console.error(err);
  process.exit(1);
});
